<body>
<a class="skip" href="#main">Skip to content</a>
<header>
  <div class="top">
    <h1>Logic Blocks</h1>
    <div class="chips" id="chips" role="status" aria-live="polite"></div>
  </div>
  <nav id="nav" role="tablist" aria-label="Screens"></nav>
</header>
<main id="main" tabindex="-1"></main>
<script>
(function () {
  'use strict';

  // ── Transport ─────────────────────────────────────────────────────────────
  // Same origin when served by the driver's relay (/app); else the ?relay=
  // pointer. The token rides ?k= and is never shown, logged or exported.
  var params = {};
  String(location.search).replace(/^\?/, '').split('&').forEach(function (p) {
    if (!p) return;
    var i = p.indexOf('=');
    params[decodeURIComponent(i < 0 ? p : p.slice(0, i))] = decodeURIComponent(i < 0 ? '' : p.slice(i + 1));
  });
  var base = params.relay || (location.protocol.indexOf('http') === 0 ? location.origin : '');
  var token = params.k || '';
  var POLL_MS = 5000;
  var STALE_AFTER_S = 20;

  function api(path, opts) {
    if (!base) return Promise.reject(new Error('This page was opened without a controller address. Open the address shown in the Dealer App property in Composer.'));
    var url = base + path + (path.indexOf('?') < 0 ? '?' : '&') + 'k=' + encodeURIComponent(token);
    var ctl = new AbortController();
    var timer = setTimeout(function () { ctl.abort(); }, 8000);
    opts = opts || {};
    opts.signal = ctl.signal;
    opts.cache = 'no-store';
    return fetch(url, opts).then(function (r) {
      clearTimeout(timer);
      return r.json().catch(function () { return {}; }).then(function (j) {
        if (r.status === 403) throw new Error('The controller refused the access token. Open the address shown in the Dealer App property again; it changes if the driver was re-added.');
        if (!r.ok && !j.error) throw new Error('The controller answered ' + r.status + '.');
        j._status = r.status;
        return j;
      });
    }, function (e) {
      clearTimeout(timer);
      throw new Error(e && e.name === 'AbortError' ? 'The controller did not answer within 8 seconds.' : 'The controller could not be reached from this device.');
    });
  }
  function post(path, body) {
    return api(path, { method: 'POST', headers: { 'Content-Type': 'text/plain' }, body: JSON.stringify(body || {}) });
  }

  // ── State ─────────────────────────────────────────────────────────────────
  var S = {
    doc: null,          // last good /state document
    fetchedAt: 0,       // browser ms when it arrived
    error: null,        // last fetch error text
    failures: 0,
    latency: null,
    loading: true,
    route: { screen: 'overview', arg: null },
    filter: { q: '', type: '', tag: '', show: '' },
    act: { slot: '', decision: '', since: '', list: null, loading: false, error: null, at: 0 },
    sb: null, sbError: null, sbBusy: false, sbSlot: ''
  };

  var SCREENS = [
    ['overview', 'Overview'], ['connections', 'Connections'], ['activity', 'Activity'],
    ['sandbox', 'Test sandbox'], ['diagnostics', 'Diagnostics'], ['help', 'Templates & help']
  ];

  // ── DOM helpers (text only: nothing typed in Composer is ever parsed as HTML)
  function h(tag, attrs, kids) {
    var el = document.createElement(tag);
    if (attrs) Object.keys(attrs).forEach(function (k) {
      var v = attrs[k];
      if (v === null || v === undefined || v === false) return;
      if (k === 'class') el.className = v;
      else if (k === 'text') el.textContent = v;
      else if (k.slice(0, 2) === 'on') el.addEventListener(k.slice(2), v);
      else el.setAttribute(k, v === true ? '' : v);
    });
    (kids || []).forEach(function (c) {
      if (c === null || c === undefined || c === false) return;
      el.appendChild(typeof c === 'string' || typeof c === 'number' ? document.createTextNode(String(c)) : c);
    });
    return el;
  }
  function t(tag, text, cls) { return h(tag, { class: cls, text: text }); }
  function chip(text, kind) { return h('span', { class: 'chip ' + (kind || 'plain'), text: text }); }
  function arr(x) { return Array.isArray(x) ? x : []; }

  // ── Time: everything the controller stamps is read against the CONTROLLER's
  // clock (generated_at + time since the answer arrived), so a wrong clock on
  // this device cannot distort "3 minutes ago".
  function controllerNow() {
    if (!S.doc) return Date.now() / 1000;
    return S.doc.generated_at + (Date.now() - S.fetchedAt) / 1000;
  }
  function span(seconds) {
    seconds = Math.max(0, Math.round(seconds));
    if (seconds < 60) return seconds + ' s';
    var m = Math.floor(seconds / 60), s = seconds % 60;
    if (m < 60) return m + ' min' + (s && m < 10 ? ' ' + s + ' s' : '');
    var hr = Math.floor(m / 60); m = m % 60;
    if (hr < 48) return hr + ' h' + (m ? ' ' + m + ' min' : '');
    return Math.floor(hr / 24) + ' d ' + (hr % 24) + ' h';
  }
  function ago(at) {
    if (at === null || at === undefined) return 'never';
    var d = controllerNow() - at;
    if (d < 0) return 'in ' + span(-d);
    if (d < 2) return 'just now';
    return span(d) + ' ago';
  }
  function clock(at) {
    if (at === null || at === undefined) return '-';
    var d = new Date(at * 1000);
    var today = new Date();
    var time = d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
    return d.toDateString() === today.toDateString() ? time : d.toLocaleDateString([], { month: 'short', day: 'numeric' }) + ' ' + time;
  }
  function stamp(at) { return at === null || at === undefined ? 'never' : clock(at) + ' (' + ago(at) + ')'; }

  // ── Freshness ─────────────────────────────────────────────────────────────
  function freshness() {
    if (!S.doc) return S.error ? 'offline' : 'loading';
    var age = (Date.now() - S.fetchedAt) / 1000;
    if (S.failures > 0 || age > STALE_AFTER_S) return 'stale';
    return 'live';
  }

  function renderChips() {
    var box = document.getElementById('chips');
    box.textContent = '';
    var f = freshness();
    if (f === 'live') box.appendChild(chip('Live · updated ' + ago(S.doc.generated_at), 'ok'));
    else if (f === 'stale') box.appendChild(chip('Stale · showing ' + clock(S.doc.generated_at), 'warn'));
    else if (f === 'offline') box.appendChild(chip('Not connected', 'bad'));
    else box.appendChild(chip('Connecting…', 'plain'));
    if (S.doc) {
      var d = S.doc.driver || {};
      if (d.read_only) box.appendChild(chip('Read-only (licence)', 'bad'));
      else box.appendChild(chip('Pack ' + (d.pack_status || 'unknown'), d.pack_status === 'active' ? 'plain' : 'warn'));
      if (S.doc.faults) box.appendChild(chip(S.doc.faults + ' need attention', 'warn'));
    }
  }

  function banners(into) {
    var f = freshness();
    if (f === 'stale') {
      into.appendChild(h('div', { class: 'banner warn', role: 'status' }, [
        t('strong', 'This is not live.'),
        'Showing what the controller reported at ' + stamp(S.doc.generated_at) + '. ' + (S.error || 'No newer answer has arrived.') + ' Countdowns below are estimates until it answers again.'
      ]));
    }
    if (S.doc && S.doc.diagnostics && S.doc.diagnostics.restore_failed) {
      into.appendChild(h('div', { class: 'banner bad', role: 'alert' }, [
        t('strong', 'Stored blocks were not loaded after the last restart.'),
        S.doc.diagnostics.restore_failed + '. Nothing was reset. In Composer, read Blocks Status, then decide whether to run Acknowledge Restore Failure.'
      ]));
    }
    if (S.doc && S.doc.driver && S.doc.driver.read_only) {
      into.appendChild(h('div', { class: 'banner bad', role: 'status' }, [
        t('strong', 'The pack is read-only.'),
        'The SmartBuildOS licence does not cover it right now. Blocks refuse every input and running countdowns are held. Nothing has been lost.'
      ]));
    }
  }

  // ── Navigation ────────────────────────────────────────────────────────────
  function parseRoute() {
    var m = String(location.hash || '').replace(/^#/, '').split('/');
    var screen = m[0] || 'overview';
    if (screen === 'block') return { screen: 'block', arg: parseInt(m[1], 10) };
    for (var i = 0; i < SCREENS.length; i++) if (SCREENS[i][0] === screen) return { screen: screen, arg: m[1] || null };
    return { screen: 'overview', arg: null };
  }
  function go(hash) { location.hash = hash; }

  function renderNav() {
    var nav = document.getElementById('nav');
    nav.textContent = '';
    var current = S.route.screen === 'block' ? 'overview' : S.route.screen;
    SCREENS.forEach(function (s, i) {
      var b = h('button', {
        role: 'tab', id: 'tab-' + s[0], 'aria-selected': s[0] === current ? 'true' : 'false',
        tabindex: s[0] === current ? '0' : '-1', text: s[1],
        onclick: function () { go(s[0]); },
        onkeydown: function (e) {
          var n = e.key === 'ArrowRight' ? i + 1 : e.key === 'ArrowLeft' ? i - 1 : e.key === 'Home' ? 0 : e.key === 'End' ? SCREENS.length - 1 : -1;
          if (n < 0) return;
          e.preventDefault();
          n = (n + SCREENS.length) % SCREENS.length;
          // Arrowing along the tabs keeps the keyboard on the tabs.
          S.focusTab = SCREENS[n][0];
          go(SCREENS[n][0]);
        }
      });
      nav.appendChild(b);
    });
  }

  // ── Shared pieces ─────────────────────────────────────────────────────────
  function blockBadges(b) {
    var out = [chip(b.label, 'plain'), chip(b.type_label, 'plain')];
    if (b.tag) out.push(chip(b.tag, 'info'));
    if (b.isolated) out.push(chip('Isolated', 'bad'));
    else if (!b.enabled) out.push(chip('Disabled', 'warn'));
    else if (b.output && b.output.valid === false) out.push(chip('Unknown', 'warn'));
    else out.push(chip('Enabled', 'ok'));
    return out;
  }
  function countdownText(b) {
    if (!b.deadline) return null;
    var left = b.deadline.at - controllerNow();
    return (left > 0 ? span(left) : 'due now') + ' until it ' + b.deadline.what;
  }
  function findBlock(slot) {
    var list = arr(S.doc && S.doc.blocks);
    for (var i = 0; i < list.length; i++) if (list[i].slot === slot) return list[i];
    return null;
  }
  function composerPath(b) {
    return 'Composer Pro → System Design → SmartBuildOS Logic Pack → Properties: set Selected Block to "' +
      (b ? (('0' + b.slot).slice(-2) + ' · ' + b.name) : 'the block') + '" → Actions: Edit Selected Block → change the Draft properties → Validate Draft → Apply Draft.';
  }
  var DECISIONS = {
    passed: ['Passed', 'ok'], suppressed: ['Suppressed', 'warn'], started: ['Started', 'info'], restarted: ['Restarted', 'info'],
    expired: ['Expired', 'ok'], expired_late: ['Expired late', 'warn'], cancelled: ['Cancelled', 'plain'], changed: ['Changed', 'ok'],
    unchanged: ['No change', 'plain'], became_true: ['Became true', 'ok'], became_false: ['Became false', 'ok'], faulted: ['Faulted', 'bad'],
    refused: ['Refused', 'bad'], isolated: ['Isolated', 'bad'], resumed: ['Resumed', 'info'], reset: ['Reset', 'plain'],
    configured: ['Configured', 'info'], enabled: ['Enabled', 'info'], disabled: ['Disabled', 'warn'], retired: ['Retired', 'warn'],
    baseline: ['Starting value', 'plain'], readable: ['Readable again', 'info'], recovered: ['Recovered', 'info'], missed: ['Missed', 'warn'],
    held: ['Held', 'warn'], feedback: ['Equipment feedback', 'info']
  };
  function decisionChip(d) { var x = DECISIONS[d] || [d, 'plain']; return chip(x[0], x[1]); }
  var ORIGINS = { live: ['Live', 'plain'], restored: ['From before the restart', 'warn'], sim: ['Simulated', 'sim'] };

  function stageRow(e) {
    var events = arr(e.events);
    var received = e.input && e.input !== '(driver)' && e.input !== '(timer)';
    var conf = e.confirmed;
    var confText = { confirmed: 'Confirmed by feedback', not_confirmed: 'No feedback arrived', already: 'Already in that state (not attributable)', pending: 'Waiting for feedback', not_monitored: 'Not monitored' }[conf] || 'Nothing to confirm';
    var names = events.map(function (k) { return (e.name ? '' : '') + ({ passed: 'Passed', started: 'Started', expired: 'Expired', cancelled: 'Cancelled', value_changed: 'Value Changed', became_true: 'Became True', became_false: 'Became False', faulted: 'Faulted' }[k] || k); });
    return h('div', { class: 'stages' }, [
      h('div', { class: 'stage ' + (received ? 'yes' : 'na') }, [t('b', '1 · Input received'), received ? e.input : (e.input === '(timer)' ? 'A countdown ended' : 'None (driver)')]),
      h('div', { class: 'stage yes' }, [t('b', '2 · Block evaluated'), (DECISIONS[e.decision] || [e.decision])[0]]),
      h('div', { class: 'stage ' + (events.length ? 'yes' : 'na') }, [t('b', '3 · Event emitted'), events.length ? names.join(', ') : 'No event']),
      h('div', { class: 'stage ' + (conf === 'confirmed' ? 'yes' : (conf === 'not_confirmed' ? 'no' : 'na')) }, [t('b', '4 · Equipment confirmed'), confText])
    ]);
  }
  function activityItem(e, withBlock) {
    var o = ORIGINS[e.origin] || [e.origin, 'plain'];
    return h('div', { class: 'act' }, [
      h('div', { class: 'head' }, [
        t('span', clock(e.at), 'mono'),
        withBlock ? t('strong', (e.name || '') + ' ') : null,
        decisionChip(e.decision),
        e.origin !== 'live' ? chip(o[0], o[1]) : null,
        t('span', ago(e.at), 'muted small'),
        e.run ? t('span', e.run + (e.cause ? ' ← ' + e.cause : ''), 'muted small mono') : null
      ]),
      t('div', e.reason || ''),
      stageRow(e)
    ]);
  }

  // ── A · Overview ──────────────────────────────────────────────────────────
  function matches(b) {
    var f = S.filter;
    if (f.type && b.type !== f.type) return false;
    if (f.tag && (b.tag || '') !== f.tag) return false;
    if (f.show === 'attention' && !(b.isolated || (b.enabled && b.output && b.output.valid === false))) return false;
    if (f.show === 'disabled' && b.enabled) return false;
    if (f.show === 'enabled' && !b.enabled) return false;
    if (f.show === 'running' && !b.deadline) return false;
    if (f.q) {
      var hay = (b.name + ' ' + (b.tag || '') + ' ' + b.type_label + ' ' + b.label + ' ' + (b.status || '')).toLowerCase();
