  // ── D · Activity ──────────────────────────────────────────────────────────
  function loadActivity() {
    var a = S.act;
    a.loading = true; a.error = null;
    var q = '/activity?limit=200';
    if (a.slot) q += '&slot=' + encodeURIComponent(a.slot);
    if (a.decision) q += '&decision=' + encodeURIComponent(a.decision);
    if (a.since) q += '&since=' + encodeURIComponent(String(Math.floor(controllerNow() - parseInt(a.since, 10))));
    return api(q).then(function (j) { a.list = arr(j.activity); a.at = j.generated_at; a.loading = false; if (S.route.screen === 'activity') render(); },
      function (e) { a.loading = false; a.error = e.message; if (S.route.screen === 'activity') render(); });
  }
  function activity(root) {
    var a = S.act;
    function sel(label, key, options) {
      return h('label', { class: 'field' }, [label, h('select', { 'aria-label': label, onchange: function (e) { a[key] = e.target.value; a.list = null; loadActivity(); render(); } },
        [h('option', { value: '', text: 'All' })].concat(options.map(function (o) { return h('option', { value: o[0], text: o[1], selected: String(a[key]) === String(o[0]) }); })))]);
    }
    root.appendChild(h('div', { class: 'controls' }, [
      sel('Block', 'slot', arr(S.doc.blocks).map(function (b) { return [String(b.slot), b.label + ' · ' + b.name]; })),
      sel('Decision', 'decision', Object.keys(DECISIONS).map(function (k) { return [k, DECISIONS[k][0]]; })),
