    root.appendChild(t('p', 'Showing ' + a.list.length + ' decisions as of ' + stamp(a.at) + '.', 'small muted'));
  }

  // ── E · Test sandbox ──────────────────────────────────────────────────────
  var CMD = { trigger: 'Trigger', start: 'Start', restart: 'Restart', cancel: 'Cancel', set: 'Set', clear: 'Clear', toggle: 'Toggle', increment: 'Increment', decrement: 'Decrement', reset: 'Reset' };
  function sbCall(path, body) {
    S.sbBusy = true; S.sbError = null; render();
    return post(path, body).then(function (j) {
      S.sbBusy = false;
      if (j.ok === false) S.sbError = j.error || 'The sandbox refused that.'; else S.sb = j.open === false ? null : j;
      render();
    }, function (e) { S.sbBusy = false; S.sbError = e.message; render(); });
  }
  function sandbox(root) {
    root.appendChild(h('div', { class: 'banner sim' }, [
      t('strong', 'Simulated. Nothing here reaches the house.'),
      'The sandbox copies a block\'s settings into a separate runtime with its own clock. It never fires a Composer event, sends a command, changes the live block or saves anything.'
    ]));
