      blocks.map(function (b) { return h('option', { value: String(b.slot), text: b.label + ' · ' + b.name + ' (' + b.type_label + ')', selected: S.sbSlot === String(b.slot) }); }));
    if (!S.sbSlot) S.sbSlot = String(blocks[0].slot);
    root.appendChild(h('div', { class: 'controls' }, [
      h('label', { class: 'field grow' }, ['Block to copy', pick]),
      h('button', { class: 'btn primary', disabled: S.sbBusy, text: S.sb ? 'Copy again (fresh sandbox)' : 'Copy settings into the sandbox', onclick: function () { sbCall('/sandbox/open', { slot: parseInt(S.sbSlot, 10) }); } }),
      S.sb ? h('button', { class: 'btn', disabled: S.sbBusy, text: 'Close sandbox', onclick: function () { sbCall('/sandbox/close', {}); } }) : null
    ]));
    if (S.sbError) root.appendChild(h('div', { class: 'banner bad', role: 'alert' }, [t('strong', 'Sandbox'), S.sbError]));
    var sb = S.sb;
    if (!sb) { root.appendChild(t('p', 'No sandbox is open. Copy a block to start; the live block keeps running untouched.', 'muted')); return; }
    var v = sb.view || {};
    var liveB = findBlock(sb.slot);
    var accepts = {};
    arr((v.wiring || {}).inputs).forEach(function (i) { accepts[i.command.replace('BLOCK_', '').toLowerCase()] = true; });
    var valueIn = h('input', { type: 'text', 'aria-label': 'Value', placeholder: 'value' });
    var byIn = h('input', { type: 'text', 'aria-label': 'By', placeholder: 'by (default 1)', style: 'max-width:130px' });
    var cmdButtons = Object.keys(CMD).filter(function (k) { return accepts[k]; }).map(function (k) {
      return h('button', { class: 'btn', disabled: S.sbBusy, text: CMD[k], onclick: function () { sbCall('/sandbox/input', { command: k, value: valueIn.value, by: byIn.value }); } });
    });
    var needsValue = accepts.set, needsBy = accepts.increment;
    var inputRows = arr(v.sources).map(function (r) {
      var f = h('input', { type: 'text', 'aria-label': 'Value for ' + r.label, placeholder: r.reads_as ? 'true / false' : 'value', value: r.value === undefined || r.value === null ? '' : String(r.value) });
      return h('div', { class: 'row', style: 'margin:6px 0' }, [
        t('span', r.label + ':', ''), f,
        h('button', { class: 'btn', disabled: S.sbBusy, text: 'Send', onclick: function () { sbCall('/sandbox/source', { index: r.index, value: f.value }); } }),
        h('button', { class: 'btn', disabled: S.sbBusy, text: 'Make unreadable', onclick: function () { sbCall('/sandbox/source', { index: r.index, unavailable: true }); } }),
        t('span', (SRC[r.status] || [r.status])[0] + (r.reads_as ? ', reads as ' + r.reads_as : ''), 'small muted')
      ]);
    });
    var custom = h('input', { type: 'number', min: '0', step: '1', value: '30', 'aria-label': 'Seconds to advance', style: 'max-width:110px' });
    var next = arr(sb.pending_timers)[0];
    function adv(s) { return h('button', { class: 'btn', disabled: S.sbBusy, text: '+' + span(s), onclick: function () { sbCall('/sandbox/advance', { seconds: s }); } }); }
    root.appendChild(h('div', { class: 'two' }, [
      h('div', { class: 'card' }, [
        h('div', { class: 'row', style: 'justify-content:space-between' }, [t('h2', 'Sandbox: ' + (v.name || '')), chip('Simulated', 'sim')]),
        t('p', v.explanation || '', 'small muted'),
        h('dl', {}, [
          t('dt', 'Simulated time'), t('dd', '+' + span(sb.elapsed) + ' after it was opened' + (sb.day ? ' · day ' + sb.day : '')),
          t('dt', 'State'), t('dd', v.status || ''),
          t('dt', 'Output'), t('dd', v.output ? 'active ' + (v.output.valid === false ? 'unknown' : (v.output.active ? 'yes' : 'no')) + ' · value ' + v.output.value + ' · state ' + v.output.state : '-'),
          t('dt', 'Next timer'), t('dd', next ? 'in ' + span(next.in_seconds) : 'none pending')
        ]),
        t('h3', 'Send an input'),
        cmdButtons.length ? h('div', { class: 'row' }, [needsValue ? valueIn : null, needsBy ? byIn : null].concat(cmdButtons)) : null,
        inputRows.length ? h('div', {}, inputRows) : null,
        t('h3', 'Move time'),
        h('div', { class: 'row' }, [adv(1), adv(10), adv(60), adv(600), adv(3600),
          next ? h('button', { class: 'btn', disabled: S.sbBusy, text: 'To the next timer', onclick: function () { sbCall('/sandbox/advance', { seconds: Math.ceil(next.in_seconds) }); } }) : null,
          custom, h('button', { class: 'btn', disabled: S.sbBusy, text: 'Advance seconds', onclick: function () { sbCall('/sandbox/advance', { seconds: parseFloat(custom.value) || 0 }); } })]),
        t('h3', 'Scenario'),
        h('div', { class: 'row' }, [
          h('button', { class: 'btn', disabled: S.sbBusy, text: 'Reset to the start', onclick: function () { sbCall('/sandbox/reset', {}); } }),
          h('button', { class: 'btn', disabled: S.sbBusy || !arr(sb.steps).length, text: 'Replay these ' + arr(sb.steps).length + ' steps', onclick: function () { sbCall('/sandbox/replay', {}); } })
        ]),
        liveB ? t('p', 'Live block right now: ' + liveB.status + ' — unaffected by anything above.', 'small muted') : null
      ]),
      h('div', { class: 'card' }, [
        t('h3', 'What would happen'),
        arr(sb.timeline).length ? h('ol', { class: 'tl' }, arr(sb.timeline).map(function (e) {
          if (e.kind === 'event') return h('li', {}, [t('span', '+' + span(e.offset) + '  ', 'mono muted'), t('span', 'Would fire: ' + e.event, 'ev')]);
          return h('li', {}, [t('span', '+' + span(e.offset) + '  ', 'mono muted'), decisionChip(e.decision), ' ', e.input && e.input.charAt(0) !== '(' ? e.input + ' → ' : '', e.reason || '']);
        })) : t('p', 'Nothing yet. Send an input or move time.', 'muted')
      ])
    ]));
  }

  // ── F · Diagnostics ───────────────────────────────────────────────────────
  function exportFile() {
    api('/export').then(function (j) {
      delete j._status;
      var blob = new Blob([JSON.stringify(j, null, 2)], { type: 'application/json' });
      var a = h('a', { href: URL.createObjectURL(blob), download: 'logic-blocks-diagnostics.json' });
      document.body.appendChild(a); a.click(); a.remove();
      setTimeout(function () { URL.revokeObjectURL(a.href); }, 5000);
    }, function (e) { alert('Export failed: ' + e.message); });
  }
  function diagnostics(root) {
    var doc = S.doc, d = doc.driver || {}, lic = doc.license || {}, dg = doc.diagnostics || {}, tr = dg.transport || {}, cl = d.clock || {}, rec = doc.recovery || {}, st = dg.stats || {}, lim = dg.limits || {}, leg = doc.legacy || {};
    function dl(rows) { return h('dl', {}, [].concat.apply([], rows.map(function (r) { return [t('dt', r[0]), h('dd', {}, [r[1] === undefined || r[1] === null || r[1] === '' ? '—' : String(r[1])])]; }))); }
    root.appendChild(h('div', { class: 'row', style: 'margin-bottom:12px' }, [
      h('button', { class: 'btn primary', text: 'Download redacted export', onclick: exportFile }),
      t('span', 'No tokens, no licence identifiers, no dealer notes. Bounded to the kept history.', 'small muted')
    ]));
    root.appendChild(h('div', { class: 'two' }, [
      h('div', { class: 'card' }, [t('h3', 'Driver'), dl([['Version', d.version], ['Driver status', d.status], ['Pack status', d.pack_status + (d.read_only ? ' (read-only)' : '')], ['Running since', d.started_at ? stamp(d.started_at) : null], ['Configuration revision', d.config_revision], ['Stored document version', d.schema_version]])]),
      h('div', { class: 'card' }, [t('h3', 'SmartBuildOS Agent and licence'), dl([['Licence status', lic.status], ['Source', lic.source], ['Tier', lic.tier]]), t('p', 'When the Agent or SmartBuildOS cannot be reached the blocks keep working. Only a definite, enforced denial makes the pack read-only.', 'small muted')]),
      h('div', { class: 'card' }, [t('h3', 'Transport and freshness'), dl([
        ['This page', tr.kind], ['Relay', tr.listening ? 'listening on port ' + tr.port : 'not listening'], ['Controller address', (tr.host || 'unknown') + ' (' + (tr.host_state || '') + ')'],
        ['Reach', tr.remote], ['Cloud summary', tr.mirror],
        ['Snapshot taken', stamp(doc.generated_at)], ['Answer time', S.latency === null ? null : S.latency + ' ms'], ['Failed requests in a row', S.failures], ['Last error', S.error]
      ])]),
      h('div', { class: 'card' }, [t('h3', 'Controller clock'), dl([['Local day', cl.day], ['Time zone', (cl.tz || '') + ' ' + (cl.utc_offset || '')], ['Basis', cl.basis], ['Last clock jump noticed', dg.clock_jump ? Math.round(dg.clock_jump.seconds) + ' s at ' + clock(dg.clock_jump.at) : 'none']])])
    ]));
    var mm = arr(dg.missing_mappings);
    root.appendChild(h('div', { class: 'card' }, [t('h3', 'Missing mappings'),
      mm.length ? h('table', { class: 'stack' }, [h('thead', {}, [h('tr', {}, ['Block', 'Input', 'Device / variable', 'Why'].map(function (x) { return t('th', x); }))]),
        h('tbody', {}, mm.map(function (m) { return h('tr', {}, [h('td', { 'data-label': 'Block' }, [('0' + m.slot).slice(-2) + ' · ' + m.name]), h('td', { 'data-label': 'Input' }, [m.input]), h('td', { 'data-label': 'Device' }, ['device ' + m.device_id + ', variable ' + m.variable_id]), h('td', { 'data-label': 'Why' }, [m.why])]); }))])
        : t('p', 'Every mapped input can be read.', 'muted')]));
    var notes = arr(rec.notes);
    root.appendChild(h('div', { class: 'card' }, [t('h3', 'Restart recovery report'),
      dl([['Last start', rec.at ? stamp(rec.at) : null], ['State saved before it', rec.saved_at ? stamp(rec.saved_at) : null], ['Blocks loaded', rec.loaded], ['Result', rec.failed ? 'NOT LOADED: ' + rec.failed : 'Loaded']]),
      notes.length ? h('ul', { class: 'plain' }, notes.map(function (x) { return t('li', x); })) : t('p', 'Nothing needed recovering.', 'muted')]));
    root.appendChild(h('div', { class: 'two' }, [
      h('div', { class: 'card' }, [t('h3', 'Counters since start'), dl([['Inputs received', st.inputs], ['Refused', st.refused], ['Events emitted', st.emitted], ['Deepest input queue', st.queued_max], ['Blocks isolated', st.isolations], ['Clock jumps', st.clock_jumps]])]),
      h('div', { class: 'card' }, [t('h3', 'Bounds'), dl([['Slots', lim.slots], ['Inputs per block', lim.inputs_per_block], ['Decisions kept', lim.history + ' (' + lim.history_saved + ' across a restart)'], ['Inputs queued', lim.queue], ['Runaway limit', lim.inputs_per_window + ' inputs to one block in ' + lim.window_s + ' s']])]),
      h('div', { class: 'card' }, [t('h3', 'Classic free-form keys'), dl([['Counters', leg.counters], ['Flags set', leg.flags], ['Timers running', leg.timers], ['Once-per-day passed', leg.once], ['State', leg.state]]), t('p', leg.note || '', 'small muted')])
    ]));
  }

  // ── G · Templates & help ──────────────────────────────────────────────────
  function help(root) {
    root.appendChild(h('div', { class: 'card' }, [
      t('h2', 'How a block is used'),
      h('ol', { class: 'steps' }, [
        t('li', 'Something happens in the house. Composer programming on that event sends a command to a block, for example BLOCK_TRIGGER (Block 03).'),
        t('li', 'The block applies its rule and decides: pass, suppress, start, expire, change.'),
        t('li', 'When it decides to act it fires its own event, for example Block 03 Passed.'),
        t('li', 'Composer programming on THAT event runs the scene, the light, the announcement. The driver does not operate equipment.')
      ]),
      t('p', S.doc.authority || '', 'muted')
    ]));
    root.appendChild(t('h2', 'Recipes'));
    arr(S.doc.templates).forEach(function (tp) {
      root.appendChild(h('section', { class: 'card', 'aria-label': tp.name }, [
        h('div', { class: 'row', style: 'justify-content:space-between' }, [t('h3', tp.name), chip(tp.type_label, 'plain')]),
        t('p', tp.summary),
        t('p', tp.explanation, 'small muted'),
        t('div', 'Settings it fills in:', 'small muted'),
        h('ul', { class: 'plain' }, arr(tp.settings).map(function (r) { return t('li', r.label + ': ' + r.value); }).concat(arr(tp.settings).length ? [] : [t('li', 'None.')])),
        arr(tp.needs).length ? h('p', {}, [chip('You pick the devices', 'warn'), ' ' + arr(tp.needs).join('; ')]) : null,
        t('div', 'In Composer:', 'small muted'),
        h('ol', { class: 'steps' }, [
          t('li', 'Properties: set Template to "' + tp.name + '". Actions: Load Template Into Draft. This fills a draft only; no block exists yet.'),
          t('li', 'Adjust Draft Name and the other Draft properties. Pick devices where the recipe needs them.'),
          t('li', 'Actions: Validate Draft, read Draft Check and Draft Impact, then Apply Draft. The Blocks property shows which slot it landed in.')
        ].concat(arr(tp.wiring).map(function (w) { return t('li', 'Programming: ' + w.replace(/\{slot\}/g, 'its slot')); })))
      ]));
    });
    root.appendChild(t('h2', 'Block types'));
    root.appendChild(h('div', { class: 'card' }, [h('table', { class: 'stack' }, [
      h('thead', {}, [h('tr', {}, ['Type', 'What it is for', 'Commands', 'Events'].map(function (x) { return t('th', x); }))]),
      h('tbody', {}, arr(S.doc.types).map(function (ty) { return h('tr', {}, [h('td', { 'data-label': 'Type' }, [t('strong', ty.label)]), h('td', { 'data-label': 'For' }, [ty.summary]), h('td', { 'data-label': 'Commands', class: 'mono' }, [arr(ty.commands).join(', ')]), h('td', { 'data-label': 'Events' }, [arr(ty.events).join(', ')])]); }))
    ])]));
    root.appendChild(t('h2', 'Words used on this page'));
    root.appendChild(h('div', { class: 'card' }, [h('dl', {}, [
      t('dt', 'Passed'), t('dd', 'The block let a trigger through and fired Passed.'),
      t('dt', 'Suppressed'), t('dd', 'The block received a trigger and its rule held it back. Nothing fired. The reason says why and when it would pass.'),
      t('dt', 'Refused'), t('dd', 'The input could not be used at all: a wrong value, a command the type does not take, a disabled or read-only block.'),
      t('dt', 'Unknown'), t('dd', 'An input cannot be read, so the block has no result. Unknown is never counted as false or zero. The block fires Faulted when it loses its result.'),
      t('dt', 'Starting value'), t('dd', 'A value read when a listener started or after a restart. It sets the state and fires nothing.'),
      t('dt', 'Isolated'), t('dd', 'A block that was fed faster than a house can (a programming loop) was stopped so the rest keeps working. Resume it in Composer.'),
      t('dt', 'The four facts'), t('dd', 'Input received, block evaluated, event emitted, equipment confirmed. The last is shown only when an equipment feedback variable is mapped; an event firing never proves the equipment moved.')
    ])]));
  }

  // ── Render ────────────────────────────────────────────────────────────────
  function render() {
    renderChips();
    renderNav();
    var root = document.getElementById('main');
    var focused = document.activeElement && document.activeElement.getAttribute && document.activeElement.getAttribute('aria-label');
    var scroll = window.scrollY;
    root.textContent = '';
    if (!S.doc) {
      if (S.error) {
        root.appendChild(h('div', { class: 'card empty', role: 'alert' }, [
          t('h2', 'Not connected to the controller'),
          t('p', S.error),
          h('ul', { class: 'plain', style: 'text-align:left;display:inline-block' }, [
            t('li', 'This device must be on the same network as the controller.'),
            t('li', 'In Composer, the Dealer App property shows the address to open; App Data Relay says whether the controller is listening.'),
            t('li', 'Dealer App Access must be On.')
          ]),
          h('p', {}, [h('button', { class: 'btn primary', text: 'Try again', onclick: function () { S.error = null; S.loading = true; render(); poll(); } })])
        ]));
      } else {
        root.appendChild(h('div', { class: 'grid', 'aria-busy': 'true', 'aria-label': 'Loading blocks' }, [h('div', { class: 'skeleton' }), h('div', { class: 'skeleton' }), h('div', { class: 'skeleton' })]));
      }
      return;
    }
    banners(root);
    var r = S.route;
    if (r.screen === 'overview') overview(root);
    else if (r.screen === 'block') blockDetail(root, r.arg);
    else if (r.screen === 'connections') connections(root, r.arg);
    else if (r.screen === 'activity') activity(root);
    else if (r.screen === 'sandbox') sandbox(root);
    else if (r.screen === 'diagnostics') diagnostics(root);
    else help(root);
    if (focused) {
      var again = root.querySelector('[aria-label="' + String(focused).replace(/"/g, '\\"') + '"]');
      if (again && again.tagName !== 'BUTTON') again.focus();
    }
    window.scrollTo(0, scroll);
  }

  // Typing in a field must not be interrupted by a poll.
  function busyTyping() {
    var a = document.activeElement;
    return a && (a.tagName === 'INPUT' || a.tagName === 'SELECT');
  }

  function poll() {
    var started = Date.now();
    return api('/state').then(function (doc) {
      S.latency = Date.now() - started;
      S.doc = doc; S.fetchedAt = Date.now(); S.error = null; S.failures = 0; S.loading = false;
      if (!busyTyping()) render(); else renderChips();
      // The activity list is its own request: keep it as fresh as the rest.
      if (S.route.screen === 'activity' && !S.act.loading && !busyTyping()) loadActivity();
    }, function (e) {
      S.error = e.message; S.failures += 1; S.loading = false;
      if (!busyTyping()) render(); else renderChips();
    });
  }

  window.addEventListener('hashchange', function () {
    S.route = parseRoute();
    if (S.route.screen === 'activity' && S.doc) loadActivity();
    render();
    var target = S.focusTab ? document.getElementById('tab-' + S.focusTab) : document.getElementById('main');
    S.focusTab = null;
    if (target) target.focus({ preventScroll: true });
    window.scrollTo(0, 0);
  });
  S.route = parseRoute();
  render();
  poll();
  setInterval(function () { if (!document.hidden) poll(); }, POLL_MS);
  // Once a second only the countdowns and the freshness chip move; the page
  // is not rebuilt, so focus and scroll position are left alone.
  setInterval(function () {
    if (document.hidden) return;
    renderChips();
    var list = document.querySelectorAll('.countdown[data-at]');
    for (var i = 0; i < list.length; i++) {
      var left = parseFloat(list[i].getAttribute('data-at')) - controllerNow();
      list[i].textContent = (left > 0 ? span(left) : 'due now') + ' until it ' + list[i].getAttribute('data-what');
    }
  }, 1000);
  document.addEventListener('visibilitychange', function () { if (!document.hidden) poll(); });
  // For tests and support: read-only handle on what the page holds.
  window.__logicBlocks = { state: S, freshness: freshness };
})();
</script>
</body>
</html>
